/**
 * Compile the given Blade template contents.
 *
 * @param  string  $value
 * @return string
 */
public function compileString($value)
{
    [$this->footer, $result] = [[], ''];

    foreach ($this->prepareStringsForCompilationUsing as $callback) {
        $value = $callback($value);
    }

    $value = $this->storeUncompiledBlocks($value);

    // First we will compile the Blade component tags. This is a precompile style
    // step which compiles the component Blade tags into @component directives
    // that may be used by Blade. Then we should call any other precompilers.
    $value = $this->compileComponentTags(
        $this->compileComments($value)
    );

    foreach ($this->precompilers as $precompiler) {
        $value = $precompiler($value);
    }

    // Here we will loop through all of the tokens returned by the Zend lexer and
    // parse each one into the corresponding valid PHP. We will then have this
    // template as the correctly rendered PHP that can be rendered natively.
    foreach (token_get_all($value) as $token) {
        $result .= is_array($token) ? $this->parseToken($token) : $token;
    }

    if (! empty($this->rawBlocks)) {
        $result = $this->restoreRawContent($result);
    }

    // If there are any footer lines that need to get added to a template we will
    // add them here at the end of the template. This gets used mainly for the
    // template inheritance via the extends keyword that should be appended.
    if (count($this->footer) > 0) {
        $result = $this->addFooters($result);
    }

    if (! empty($this->echoHandlers)) {
        $result = $this->addBladeCompilerVariable($result);
    }

    return str_replace(
        ['##BEGIN-COMPONENT-CLASS##', '##END-COMPONENT-CLASS##'],
        '',
        $result);
}

/**
 * Evaluate and render a Blade string to HTML.
 *
 * @param  string  $string
 * @param  array  $data
 * @param  bool  $deleteCachedView
 * @return string
 */
public static function render($string, $data = [], $deleteCachedView = false)
{
    $component = new class($string) extends Component
    {
        protected $template;

        public function __construct($template)
        {
            $this->template = $template;
        }

        public function render()
        {
            return $this->template;
        }
    };

    $view = Container::getInstance()
                ->make(ViewFactory::class)
                ->make($component->resolveView(), $data);

    return tap($view->render(), function () use ($view, $deleteCachedView) {
        if ($deleteCachedView) {
            @unlink($view->getPath());
        }
    });
}

/**
 * Render a component instance to HTML.
 *
 * @param  \Illuminate\View\Component  $component
 * @return string
 */
public static function renderComponent(Component $component)
{
    $data = $component->data();

    $view = value($component->resolveView(), $data);

    if ($view instanceof View) {
        return $view->with($data)->render();
    } elseif ($view instanceof Htmlable) {
        return $view->toHtml();
    } else {
        return Container::getInstance()
            ->make(ViewFactory::class)
            ->make($view, $data)
            ->render();
    }
}

/**
 * Store the blocks that do not receive compilation.
 *
 * @param  string  $value
 * @return string
 */
protected function storeUncompiledBlocks($value)
{
    if (str_contains($value, '@verbatim')) {
        $value = $this->storeVerbatimBlocks($value);
    }

    if (str_contains($value, '@php')) {
        $value = $this->storePhpBlocks($value);
    }

    return $value;
}

/**
 * Store the verbatim blocks and replace them with a temporary placeholder.
 *
 * @param  string  $value
 * @return string
 */
protected function storeVerbatimBlocks($value)
{
    return preg_replace_callback('/(?<!@)@verbatim(.*?)@endverbatim/s', function ($matches) {
        return $this->storeRawBlock($matches[1]);
    }, $value);
}

/**
 * Store the PHP blocks and replace them with a temporary placeholder.
 *
 * @param  string  $value
 * @return string
 */
protected function storePhpBlocks($value)
{
    return preg_replace_callback('/(?<!@)@php(.*?)@endphp/s', function ($matches) {
        return $this->storeRawBlock("<?php{$matches[1]}?>");
    }, $value);
}

/**
 * Store a raw block and return a unique raw placeholder.
 *
 * @param  string  $value
 * @return string
 */
protected function storeRawBlock($value)
{
    return $this->getRawPlaceholder(
        array_push($this->rawBlocks, $value) - 1
    );
}

/**
 * Compile the component tags.
 *
 * @param  string  $value
 * @return string
 */
protected function compileComponentTags($value)
{
    if (! $this->compilesComponentTags) {
        return $value;
    }

    return (new ComponentTagCompiler(
        $this->classComponentAliases, $this->classComponentNamespaces, $this
    ))->compile($value);
}

/**
 * Replace the raw placeholders with the original code stored in the raw blocks.
 *
 * @param  string  $result
 * @return string
 */
protected function restoreRawContent($result)
{
    $result = preg_replace_callback('/'.$this->getRawPlaceholder('(\d+)').'/', function ($matches) {
        return $this->rawBlocks[$matches[1]];
    }, $result);

    $this->rawBlocks = [];

    return $result;
}

/**
 * Get a placeholder to temporarily mark the position of raw blocks.
 *
 * @param  int|string  $replace
 * @return string
 */
protected function getRawPlaceholder($replace)
{
    return str_replace('#', $replace, '@__raw_block_#__@');
}

